INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1378a28d-d40d-460b-a787-4c1b368b9314', 'radical', '手', 'hand', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Yang ini agak sulit untuk dibayangkan, tapi aku percaya padamu. Duri di tengah adalah pergelangan tangan/lengan. Lalu, ada empat jari biasa yang keluar dan satu ibu jari besar (slide radikal di atas). Jadi Anda memiliki empat jari, satu ibu jari, dan satu pergelangan tangan. Inilah yang membuat tangan Anda tampak gila.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1378a28d-d40d-460b-a787-4c1b368b9314', 'Tangan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('efa2cc8d-a592-4ce1-8b40-e35cc02c43ed', 'radical', '方', 'direction', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal ini terlihat seperti pria yang lari ke kanan. Dia menuju ke arah yang sangat berbeda. Ke arah mana lagi?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('efa2cc8d-a592-4ce1-8b40-e35cc02c43ed', 'Arah', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('da98c2a3-db4f-4217-8fb1-570bfce7105e', 'radical', '心', 'heart', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Perhatikan baik-baik yang ini. Bentuknya seperti hati (meskipun bukan jantung khas Hari Valentine). Pikirkan hati yang nyata. Pada dasarnya, terdapat benjolan (jantung) di tengahnya, dan tiga garis yang membentuk arteri yang masuk dan keluar dari jantung untuk membuat Anda tetap hidup. Radikal ini sering muncul, jadi tidak akan terlalu sulit untuk mempelajarinya seiring berjalannya waktu. Ingat, benjolan (jantung) ditambah pembuluh darah sama dengan jantung… seperti, jantung asli, bukan palsu, cantik.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('da98c2a3-db4f-4217-8fb1-570bfce7105e', 'Jantung', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9dcc7e8e-fadc-474d-8fba-0fd5b557d21d', 'radical', '不', 'not', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Jika Anda melihat radikal ini dalam sebuah kanji, Anda pasti ingin memikirkan kebalikan dari radikal apa pun yang ada. Kelihatannya sangat mirip "di bawah", tapi coba tebak? Ini bukan radikal di bawah ini. Hanya saja tidak.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9dcc7e8e-fadc-474d-8fba-0fd5b557d21d', 'Bukan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('1c6f4519-94ba-4430-9fa4-d8219ed0c71c', 'radical', '元', 'origin', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda memiliki dua kaki yang membentuk radikal ini. Di antara dua kaki adalah tempat asalmu, tidak peduli bagaimana kamu melihatnya. Kedua kaki ini adalah asal muasalmu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('1c6f4519-94ba-4430-9fa4-d8219ed0c71c', 'Asal', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('9de45f4d-39b5-4b91-9d16-84f4d4620c23', 'radical', '丿', 'slide', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Tutup mata Anda dan bayangkan Anda menjadi anak-anak lagi. Sekarang buka dan... lihat! Itu perosotan! Bayangkan Anda meluncur ke bawah slide ini berulang kali, bersenang-senang. Imajinasi + emosi menghasilkan hafalan yang baik!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('9de45f4d-39b5-4b91-9d16-84f4d4620c23', 'Geser', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5083654b-e17f-4c61-a5df-5f1131393d99', 'radical', '止', 'stop', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ada jari kaki raksasa dan tongkat di tanah di depan Anda. Anda mengendarai mobil Anda ke arah mereka, tetapi Anda tidak melihatnya sampai lampu Anda menyinari mereka. Hal-hal ini menyebabkan Anda melakukan apa? Kemungkinan besar segera hentikan mobil Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5083654b-e17f-4c61-a5df-5f1131393d99', 'Berhenti', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('97d9b601-356a-44d2-bb19-212d3030602e', 'radical', '文', 'writing', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Bentuknya seperti bangku dengan penutup di atasnya, namun sebenarnya ini adalah meja tulis. Apakah kamu melihatnya? Ini tempat yang bagus dan tenang untuk menulis. Anda bahkan dapat melihat pena mencuat di tengah. Tidakkah Anda ingin menulis di sini?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('97d9b601-356a-44d2-bb19-212d3030602e', 'Menulis', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4d0f9a32-40f6-4753-8270-6269025b6fe4', 'radical', 'ム', 'private', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ini adalah segitiga kecil yang hampir tertutup seluruhnya. Saat Anda ingin sendiri, Anda bersembunyi di tempat di mana Anda bisa menyendiri. Itu sebabnya ini disebut radikal swasta. Anda menutup diri dari dunia luar, hanya dengan sedikit lubang intip.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4d0f9a32-40f6-4753-8270-6269025b6fe4', 'Pribadi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ed00bbcd-79b2-4970-94b3-cc640db13ede', 'radical', '犬', 'dog', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ingat orang besar yang membantu Anda mengingat orang radikal besar? Sekarang lelaki besar itu mempunyai sesuatu di bahunya... apa itu? Anda melihat dan melihat bahwa dia mempunyai seekor anjing di atas sana, bertengger seolah-olah itu adalah burung beo atau kucing atau semacamnya. Anjing tidak seharusnya berada di pundak orang seperti itu, tapi untuk dia? Itu berhasil!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ed00bbcd-79b2-4970-94b3-cc640db13ede', 'Anjing', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('26564c95-7e33-4658-87d6-1d0216972ea1', 'radical', '牛', 'cow', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ada salib dan pistol, dengan pistol menembus salib. Anda menggunakan salib untuk menstabilkan senjata Anda, karena Anda perlu menembak sapi untuk makan malam. Anda membawa salib Anda karena Anda perlu memberkati sapi itu setelah Anda membunuhnya (dan itu juga merupakan tempat yang baik untuk senjata Anda). Sapi yang malang.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26564c95-7e33-4658-87d6-1d0216972ea1', 'Sapi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('c59efbef-e607-4c07-82c1-1a29cd7ced99', 'radical', '立', 'stand', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Dua batang kayu menopang tutupnya. Dengan melakukan ini, mereka membuatnya berdiri.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c59efbef-e607-4c07-82c1-1a29cd7ced99', 'Berdiri', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('5982d2d2-b74d-4059-ae6f-c5cd5765cef6', 'radical', '用', 'task', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ini terlihat seperti kalender dengan ruang untuk Anda menulis tugas Anda hari itu. Lihat bagian kosong itu? Pastikan Anda menuliskan tugas harian Anda, agar tidak lupa melakukan sesuatu yang penting!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5982d2d2-b74d-4059-ae6f-c5cd5765cef6', 'Tugas', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('ae029774-b184-41ec-b673-8c9dffabd852', 'radical', 'ｲ', 'leader', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata radikal ini secara teknis berarti orang (seperti 人), namun kita akan mengubah maknanya sedikit. Ini seperti orang radikal, tapi lebih tinggi dan lebih kurus, berdiri di atas prajurit infanteri lainnya. Itu sebabnya dia adalah seorang pemimpin, bukan orang tua biasa.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('ae029774-b184-41ec-b673-8c9dffabd852', 'Pemimpin', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fe2e6a28-9f37-480f-a2ef-25135ff5a3c3', 'radical', '弋', 'ceremony', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal ini terlihat seperti orang dengan gaun panjang atau kereta api yang berjalan di belakangnya. Itu karena calon pengantin akan menghadiri upacara pernikahan mereka! Biasanya Anda harus mengenakan gaun panjang atau jubah jika berada di sebuah upacara. Jadi ketika Anda melihat hal radikal ini, pikirkan semua upacara berbeda yang mungkin harus Anda hadiri dalam hidup Anda dan apa yang perlu Anda kenakan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fe2e6a28-9f37-480f-a2ef-25135ff5a3c3', 'Upacara', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('4e45c6ae-cbba-4d18-9d48-2fa2532ffc74', 'radical', '世', 'world', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Tidak ada lingkaran dalam kanji, ingat? Jadi bayangkan sudut-sudut ini benar-benar berbentuk lingkaran. Lingkaran kecil dalam lingkaran besar, dengan garis melewatinya. Wah, ini dunia. Dunia terlihat seperti ini, dengan benua di dunia dan sebuah garis adalah garis khatulistiwa. Bisakah kamu melihatnya?') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('4e45c6ae-cbba-4d18-9d48-2fa2532ffc74', 'Dunia', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('0b702446-a297-447f-a803-0cd18a4f486a', 'radical', 'L', 'lion', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal berbentuk L ini adalah radikal singa, karena "L berarti Singa". Ini juga terlihat seperti mulut singa yang terbuka sangat-sangat lebar. Bayangkan seekor singa membuka mulutnya untuk menguap. Sepertinya ini radikal!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('0b702446-a297-447f-a803-0cd18a4f486a', 'Singa', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('7a124b58-3465-4b16-9d7c-9ce2d81b5c46', 'radical', '丶', 'drop', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal kecil ini adalah setetes air atau cairan lainnya. Perhatikan bagaimana itu hanya satu tetes? Terkadang radikal atau kanji memiliki lebih dari satu huruf, jadi penting bagi Anda untuk mengetahui cara membedakannya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('7a124b58-3465-4b16-9d7c-9ce2d81b5c46', 'Jatuhkan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('e40b5a77-856c-43c4-90f9-9d116b621542', 'radical', '主', 'master', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Raja ini mempunyai setetes air yang mengambang di atas kepalanya. Itu karena dia bukan hanya seorang raja, dia adalah penguasa air. Ahli elemen. Penguasa Segala Sesuatu!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e40b5a77-856c-43c4-90f9-9d116b621542', 'Guru', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, description) VALUES ('fa18252d-ef0d-421d-91bb-b6283a10bd4b', 'radical', '可', 'lip-ring', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ada sesuatu yang ketagihan masuk ke dalam mulut. Namun, bukan pengait, itu adalah cincin bibir. Mereka biasa menggunakan kail dan paku ikan di masa lalu. (Senang kita tidak hidup di masa itu lagi!)') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fa18252d-ef0d-421d-91bb-b6283a10bd4b', 'Cincin Bibir', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('e0f1e139-fa80-4e51-96d8-60a9f9e6deb1', 'kanji', '力', '力', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal dan makna kanji ini sama. Keduanya adalah kekuatan.', 'Siapakah yang mempunyai kekuasaan paling besar di antara semua orang? Itu adalah Power Rangers. Mereka melawan musuh bebuyutan mereka Ricky (りき). Mereka mengalahkannya dan mengunci (りょく) dia, sehingga dia tidak bisa menyakiti siapa pun lagi.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
