INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('fe1c12e2-592c-4085-8db1-16e923d27772', 'kanji', '手', '手', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal tangan dan kanji tangan memiliki tampilan dan makna yang identik! Itu seharusnya membuat segalanya menjadi mudah!', 'Untuk mengingat bacaannya て kita akan menggunakan kata "Televisi". Anda memiliki tangan yang bagus. Silakan lihat mereka. ASTAGA. Anda memiliki televisi kecil (て) di tangan Anda. Mereka juga memainkan pertunjukan paling bodoh yang dapat Anda pikirkan, dengan kedua tangan pada saat yang bersamaan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
