INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('fdb76ab7-02d9-4791-9280-71b45e40ae94', 'kanji', '文', '文', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanji dan radikalnya sama, jadi mengingat arti kanji ini semudah memastikan Anda mengetahui radikal penulisannya terlebih dahulu! Jika Anda tahu radikalnya, Anda pasti tahu kanji ini juga berarti menulis.', 'Kanji ini memiliki lebih dari satu bacaan penting yang perlu Anda pelajari, maaf! Namun jangan khawatir, berikut ini mnemonik untuk membantu Anda:
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fdb76ab7-02d9-4791-9280-71b45e40ae94', 'Menulis', true) ON CONFLICT DO NOTHING;
