INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('0ab21533-8d9d-474c-9269-c80ecc0cfdb3', 'いぬ', 'kunyomi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('e66cacc3-8efa-42b4-b5a2-bbc5903fd1be', 'kanji', '牛', '牛', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Radikal dan kanji untuk sapi sama persis! Itu membuatnya mudah untuk diingat, selama Anda mengenal radikal Anda dengan cukup baik.', 'Pernahkah Anda mendengar tentang daging sapi わぎゅう?ぎゅう itu adalah ぎゅう.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
