INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('57039dbc-7af0-4505-be71-08d09465e212', 'kanji', '世', '世', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata radikal dunia dan kanji dunia itu sama, namun ada arti lain yang sangat penting yang perlu Anda ketahui: generasi. 
