INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('eb24585c-7a09-42de-8633-59a57a02bab6', 'kanji', '正', '正', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ada garis di tanah sehingga Anda berhenti dan muncul tanda raksasa yang bertuliskan BENAR! Anda mematuhi peraturan lalu lintas dan melakukan hal yang benar.', 'Kamu melakukan hal yang benar, jadi Shougun (しょう) muncul untuk memberimu hadiah! Dia mengulurkan pedang (せい) baru yang mengilap di tangannya, dengan lembut mengetukkannya ke masing-masing bahu Anda, dan kemudian menyerahkannya kepada Anda. Itu besar, melengkung dan Anda menyukainya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
