INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('0dedcc46-3e44-403e-91d4-a75ed65d4a64', 'kanji', '以', '以', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Singa menjatuhkan setetes air liur ke orang ini dari atas. Keadaan orang tersebut jauh lebih buruk dibandingkan dengan sebelumnya, karena mereka baru saja jatuh ke dalam lubang ini.', 'Dari atas terdengar suara gaok yang keras, dan seekor elang raksasa (い) menukik ke bawah, memaksa singa tersebut mundur. Elang menangkap orang tersebut dengan cakarnya, membawanya ke udara! Tapi sekarang dia... di udara dibawa oleh elang raksasa, dibandingkan dengan dimana dia sebelumnya, apakah ini lebih baik?!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
