INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, reading_mnemonic) VALUES ('542d3210-7fbb-4f22-98e5-2880c92b401f', 'kanji', '台', '台', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Anda memiliki mulut pribadi yang merupakan mesin. Namun Anda harus merahasiakan mulut mesin Anda karena hal itu akan menakuti semua orang non-mesin di sekitar Anda.', 'Untuk memastikan mereka tidak bisa membedakan mana yang mesin dan mana yang manusia, kamu mewarnai (だい) mulutnya agar terlihat seperti kulit. Anda menemukan pewarna dengan warna yang sama dengan mulut normal Anda dan cukup mengoleskannya di sana.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, reading_mnemonic = EXCLUDED.reading_mnemonic;
