INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d7bcd275-0788-4950-af8c-3db303f45de8', 'vocabulary', '力', '力', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Ketika sebuah kata kosakata terdiri dari satu kanji dan hanya itu, hampir selalu maknanya diambil dari kanji induknya. Jadi, vocab kata ini juga berarti kekuasaan.', 'Ketika sebuah kata kosakata terdiri dari satu kanji dan hanya itu, hampir selalu maknanya diambil dari kanji induknya. Jadi, vocab kata ini juga berarti kekuasaan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
