INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('7ee772b1-383d-4b2f-a9f2-904be213eac5', 'ゆうべ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ee772b1-383d-4b2f-a9f2-904be213eac5', '夕べ、パーティーにいきました。', 'Saya pergi ke pesta tadi malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ee772b1-383d-4b2f-a9f2-904be213eac5', 'デンマークの王子はフランス人二人をおんがくの夕べにしょうたいしました。', 'Pangeran di Denmark mengundang dua orang Prancis ke malam musik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('7ee772b1-383d-4b2f-a9f2-904be213eac5', '夕べ、ひたいに肉とかいてみた。', 'Tadi malam saya menulis kanji untuk daging di dahi saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('4aef0f92-1adf-4b68-9a7d-147187046908', 'vocabulary', '手', '手', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanjinya berarti tangan, dan kata itu juga berarti tangan! Ini juga dapat digunakan untuk merujuk pada seluruh lengan Anda.', 'Kanjinya berarti tangan, dan kata itu juga berarti tangan! Ini juga dapat digunakan untuk merujuk pada seluruh lengan Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
