INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('8f985df2-785c-4d26-856f-9c0ce8e9c362', 'へた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f985df2-785c-4d26-856f-9c0ce8e9c362', 'ギターはまだ下手ですが、まいばんれんしゅうしています。', 'Saya masih buruk dalam bermain gitar, tetapi saya berlatih setiap malam.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f985df2-785c-4d26-856f-9c0ce8e9c362', 'アメリカ人のまねが下手な人は、フランス人のまねが上手です。', 'Orang yang tidak pandai meniru orang Amerika, pandai meniru orang Prancis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8f985df2-785c-4d26-856f-9c0ce8e9c362', 'わたしははをみがくのが下手です。', 'Aku buruk dalam menyikat gigi.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('2cb97827-0486-4265-a852-ccec1c46c8f5', 'vocabulary', '上手', '上手', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Bayangkan seseorang mengulurkan tangannya. Ini rata-rata. Hal-hal yang dinilai di bawah kendali adalah hal-hal yang tidak Anda kuasai. Hal-hal yang dinilai di atas adalah hal-hal yang Anda kuasai.', 'Bayangkan seseorang mengulurkan tangannya. Ini rata-rata. Hal-hal yang dinilai di bawah kendali adalah hal-hal yang tidak Anda kuasai. Hal-hal yang dinilai di atas adalah hal-hal yang Anda kuasai.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
