INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2cb97827-0486-4265-a852-ccec1c46c8f5', 'さとうさんは、うたを上手にうたいます。', 'Satou pandai menyanyi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2cb97827-0486-4265-a852-ccec1c46c8f5', 'オリーブオイルのつかいかたが上手な王子をしっていますか。', 'Tahukah Anda ada pangeran yang pandai menggunakan minyak zaitun?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2cb97827-0486-4265-a852-ccec1c46c8f5', 'わたしはへんがおをつくるのが上手です。', 'Saya pandai membuat wajah lucu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1f6e24ad-ebe2-4c75-a659-5f0c0f4a1a67', 'vocabulary', '文', '文', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
