INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('1f6e24ad-ebe2-4c75-a659-5f0c0f4a1a67', 'ぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f6e24ad-ebe2-4c75-a659-5f0c0f4a1a67', 'はやく文をよんでください。', 'Tolong baca kalimatnya lebih cepat.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f6e24ad-ebe2-4c75-a659-5f0c0f4a1a67', 'おどろいたことに、そのアメリカ人の文はイギリス人のわたしの文よりえいごが上手にかけていました。', 'Yang mengejutkan saya, tulisan bahasa Inggris orang Amerika ditulis lebih baik daripada tulisan saya, dan saya orang Inggris.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('1f6e24ad-ebe2-4c75-a659-5f0c0f4a1a67', 'かなしい文をよむと、いつもなみだが二ふん二十びょうだけとまらない。', 'Setiap kali saya membaca cerita sedih, saya tidak bisa berhenti menangis selama dua menit dua puluh detik.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('047fd314-c5a2-4ca6-9065-1df50b36a58a', 'vocabulary', '犬', '犬', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kosakata yang terdiri dari satu kanji ini memiliki arti yang sama dengan kanji tunggal tersebut. Artinya adalah anjing.', 'Kosakata yang terdiri dari satu kanji ini memiliki arti yang sama dengan kanji tunggal tersebut. Artinya adalah anjing.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('047fd314-c5a2-4ca6-9065-1df50b36a58a', 'Anjing', true) ON CONFLICT DO NOTHING;
