INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c58f9d31-5e27-41db-91e6-bd8e70380f73', 'そこは出口ではありません。', 'Itu bukanlah jalan keluar.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c58f9d31-5e27-41db-91e6-bd8e70380f73', 'ふじ山にはひみつの入り口と出口があるらしいですよ。', 'Saya mendengar bahwa Gunung Fuji memiliki pintu masuk dan keluar rahasia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c58f9d31-5e27-41db-91e6-bd8e70380f73', 'このきゅうじょうの出口はあちらです。', 'Pintu keluar stadion bisbol ada di sana.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('1730b1c0-a124-461a-9813-a4cf438c1cbe', 'vocabulary', '右手', '右手', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Tangan kananmu adalah tangan kananmu! Kata ini juga dapat digunakan untuk mengartikan lengan kanan, dan sisi kanan.', 'Tangan kananmu adalah tangan kananmu! Kata ini juga dapat digunakan untuk mengartikan lengan kanan, dan sisi kanan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
