INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f76efd-5cb9-4719-b0f2-42d5777d6724', 'あねの左手には、ほくろがある。', 'Kakak perempuan saya mempunyai tahi lalat di tangan kirinya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f76efd-5cb9-4719-b0f2-42d5777d6724', '左手を上げてください。', 'Silakan angkat tangan kiri Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f76efd-5cb9-4719-b0f2-42d5777d6724', '左手のひじをハチにさされた。', 'Saya disengat lebah di siku lengan kiri saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e0f76efd-5cb9-4719-b0f2-42d5777d6724', '左手にみえるのが、スカイツリーです。', 'Apa yang bisa Anda lihat di sisi kiri Anda adalah Pohon Langit.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d61f1cbd-c8ed-4247-97fe-744051d510c0', 'vocabulary', '正しい', '正しい', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Diakhiri dengan い memberitahu Anda bahwa kata ini adalah kata sifat い. Jadi karena Anda tahu bahwa kanji 正 berarti "benar", apa versi kata sifat dari kata tersebut? Ya, itu juga benar.', 'Diakhiri dengan い memberitahu Anda bahwa kata ini adalah kata sifat い. Jadi karena Anda tahu bahwa kanji 正 berarti "benar", apa versi kata sifat dari kata tersebut? Ya, itu juga benar.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
