INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('2355f74a-b30b-4aec-93f6-f7a9366d7eb4', 'あしたはかぞくみんなで田をたがやします。', 'Besok kami menggarap sawah bersama seluruh keluarga.') ON CONFLICT DO NOTHING;
