INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba65942b-d55f-4398-94b7-b57ce8811391', 'これは、メアリーが大切にしている人ぎょうです。', 'Ini adalah boneka yang Maria perlakukan dengan sangat hati-hati.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba65942b-d55f-4398-94b7-b57ce8811391', 'そばにいてくれる友人やこい人、かぞくを大切にした方がいいですよ。', 'Anda harus menghargai teman, pasangan, dan keluarga yang mendukung Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('ba65942b-d55f-4398-94b7-b57ce8811391', '大切なしょるいときくと、いつも中みをみたくなる。', 'Setiap kali saya mendengar bahwa suatu dokumen sangat penting, saya selalu ingin melihat apa yang ada di dalamnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('9d8f66c6-133d-4aa8-9586-001bfbc492c9', 'vocabulary', '切る', '切る', 2, 'd4e5f6a7-b8c9-0d1e-2f3a-4b5c6d7e8f9a', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri artinya memotong, dan bentuk kata kerjanya adalah memotong.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri artinya memotong, dan bentuk kata kerjanya adalah memotong.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
